SELECT '1. 28 支函式全部存在（含 bulk_upsert 兩個多載）' AS item, (SELECT count(*) FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname IN ('_hotelnabe_enqueue_days', 'acquire_group_buy_payment_hold', 'bulk_upsert_room_inventory_pricing', 'cleanup_old_error_logs', 'cleanup_old_monitoring_logs', 'consume_trip_product_stock', 'convert_group_buy_payment_draft', 'delete_group_buy_campaign', 'delete_package_season', 'delete_pricing_template_group', 'ensure_trip_share_slug', 'gbp_save_accommodation_oauth_client_secret', 'gbp_vault_delete', 'import_ryoan_order_bypass', 'increment_member_push_badge', 'recalc_course_profit_payouts', 'scan_stuck_group_buy_paid_drafts', 'seed_app_review_account', 'set_discount_code_template_groups', 'set_pricing_template_group_members', 'verify_accommodation_ai_api_key', 'verify_accommodation_api_key', 'verify_owlting_service_account', 'wizard_open_inventory', 'wizard_save_basic_info', 'wizard_save_package', 'wizard_save_room_type')) = 28 AS ok
UNION ALL SELECT '2. 28 支全部是 SECURITY DEFINER', NOT EXISTS (SELECT 1 FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname IN ('_hotelnabe_enqueue_days', 'acquire_group_buy_payment_hold', 'bulk_upsert_room_inventory_pricing', 'cleanup_old_error_logs', 'cleanup_old_monitoring_logs', 'consume_trip_product_stock', 'convert_group_buy_payment_draft', 'delete_group_buy_campaign', 'delete_package_season', 'delete_pricing_template_group', 'ensure_trip_share_slug', 'gbp_save_accommodation_oauth_client_secret', 'gbp_vault_delete', 'import_ryoan_order_bypass', 'increment_member_push_badge', 'recalc_course_profit_payouts', 'scan_stuck_group_buy_paid_drafts', 'seed_app_review_account', 'set_discount_code_template_groups', 'set_pricing_template_group_members', 'verify_accommodation_ai_api_key', 'verify_accommodation_api_key', 'verify_owlting_service_account', 'wizard_open_inventory', 'wizard_save_basic_info', 'wizard_save_package', 'wizard_save_room_type') AND NOT p.prosecdef)
UNION ALL SELECT '3. 沒有 SECURITY INVOKER 函式呼叫要收回 authenticated 的 17 個函式名', NOT EXISTS (SELECT 1 FROM pg_proc p CROSS JOIN unnest(ARRAY['acquire_group_buy_payment_hold', 'bulk_upsert_room_inventory_pricing', 'cleanup_old_error_logs', 'cleanup_old_monitoring_logs', 'consume_trip_product_stock', 'convert_group_buy_payment_draft', 'delete_group_buy_campaign', 'gbp_save_accommodation_oauth_client_secret', 'gbp_vault_delete', 'import_ryoan_order_bypass', 'increment_member_push_badge', 'recalc_course_profit_payouts', 'scan_stuck_group_buy_paid_drafts', 'seed_app_review_account', 'verify_accommodation_ai_api_key', 'verify_accommodation_api_key', 'verify_owlting_service_account']) AS n(nm) WHERE p.pronamespace = 'public'::regnamespace AND NOT p.prosecdef AND p.proname <> n.nm AND p.prosrc ~ ('\m' || n.nm || '\M'))
UNION ALL SELECT '4. 沒有 RLS policy 引用 A 類函式', NOT EXISTS (SELECT 1 FROM pg_policy pol CROSS JOIN unnest(ARRAY['_hotelnabe_enqueue_days', 'acquire_group_buy_payment_hold', 'bulk_upsert_room_inventory_pricing', 'cleanup_old_error_logs', 'cleanup_old_monitoring_logs', 'consume_trip_product_stock', 'convert_group_buy_payment_draft', 'delete_group_buy_campaign', 'gbp_save_accommodation_oauth_client_secret', 'gbp_vault_delete', 'import_ryoan_order_bypass', 'increment_member_push_badge', 'recalc_course_profit_payouts', 'scan_stuck_group_buy_paid_drafts', 'seed_app_review_account', 'verify_accommodation_ai_api_key', 'verify_accommodation_api_key', 'verify_owlting_service_account']) AS n(nm) WHERE COALESCE(pg_get_expr(pol.polqual, pol.polrelid), '') || ' ' || COALESCE(pg_get_expr(pol.polwithcheck, pol.polrelid), '') ~ ('\m' || n.nm || '\M'))
UNION ALL SELECT '5. 課程分潤觸發器函式 fn_course_profit_months_sync／fn_course_profit_rates_sync 是 SECURITY DEFINER', (SELECT bool_and(p.prosecdef) AND count(*) = 2 FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname IN ('fn_course_profit_months_sync', 'fn_course_profit_rates_sync'))
UNION ALL SELECT '6. hotelnabe 觸發器函式 fn_hotelnabe_enqueue_from_order／order_rooms／rip 是否 SECURITY DEFINER（僅記錄，本批保留 authenticated 不受影響）', (SELECT bool_and(p.prosecdef) AND count(*) = 3 FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname IN ('fn_hotelnabe_enqueue_from_order', 'fn_hotelnabe_enqueue_from_order_rooms', 'fn_hotelnabe_enqueue_from_rip'))
UNION ALL SELECT '7. 20261031090000 已上線：change_order_dates 含 ORDER_MODULE_GUARD_V1', (SELECT position('ORDER_MODULE_GUARD_V1' IN p.prosrc) > 0 FROM pg_proc p WHERE p.oid = to_regprocedure('public.change_order_dates(uuid, date, date, text, text, text)'));

SELECT p.oid::regprocedure::text AS func,
       CASE WHEN p.proname = '_hotelnabe_enqueue_days' THEN 'A-partial' WHEN p.proname = 'ensure_trip_share_slug' THEN 'B' WHEN p.proname IN ('delete_package_season', 'delete_pricing_template_group', 'set_discount_code_template_groups', 'set_pricing_template_group_members', 'wizard_open_inventory', 'wizard_save_basic_info', 'wizard_save_package', 'wizard_save_room_type') THEN 'C' ELSE 'A' END AS klass,
       pg_get_userbyid(p.proowner) AS owner, p.prosecdef AS secdef, COALESCE(p.proacl::text, 'NULL') AS proacl,
       EXISTS (SELECT 1 FROM aclexplode(COALESCE(p.proacl, acldefault('f', p.proowner))) a WHERE a.grantee = 0 AND a.privilege_type = 'EXECUTE') AS has_public,
       has_function_privilege('anon', p.oid, 'EXECUTE') AS anon_exec, has_function_privilege('authenticated', p.oid, 'EXECUTE') AS auth_exec, has_function_privilege('service_role', p.oid, 'EXECUTE') AS service_exec,
       md5(replace(p.prosrc, E'\r', '')) AS fp
FROM pg_proc p
WHERE p.pronamespace = 'public'::regnamespace AND p.proname IN ('_hotelnabe_enqueue_days', 'acquire_group_buy_payment_hold', 'bulk_upsert_room_inventory_pricing', 'cleanup_old_error_logs', 'cleanup_old_monitoring_logs', 'consume_trip_product_stock', 'convert_group_buy_payment_draft', 'delete_group_buy_campaign', 'delete_package_season', 'delete_pricing_template_group', 'ensure_trip_share_slug', 'gbp_save_accommodation_oauth_client_secret', 'gbp_vault_delete', 'import_ryoan_order_bypass', 'increment_member_push_badge', 'recalc_course_profit_payouts', 'scan_stuck_group_buy_paid_drafts', 'seed_app_review_account', 'set_discount_code_template_groups', 'set_pricing_template_group_members', 'verify_accommodation_ai_api_key', 'verify_accommodation_api_key', 'verify_owlting_service_account', 'wizard_open_inventory', 'wizard_save_basic_info', 'wizard_save_package', 'wizard_save_room_type')
ORDER BY 1;

SELECT 'FP_ALL（貼入 postcheck 的 __PASTE_PRECHECK_FP_ALL__）' AS item, md5(string_agg(p.oid::regprocedure::text || '=' || md5(replace(p.prosrc, E'\r', '')), ',' ORDER BY p.oid::regprocedure::text)) AS value
FROM pg_proc p
WHERE p.pronamespace = 'public'::regnamespace AND p.proname IN ('_hotelnabe_enqueue_days', 'acquire_group_buy_payment_hold', 'bulk_upsert_room_inventory_pricing', 'cleanup_old_error_logs', 'cleanup_old_monitoring_logs', 'consume_trip_product_stock', 'convert_group_buy_payment_draft', 'delete_group_buy_campaign', 'delete_package_season', 'delete_pricing_template_group', 'ensure_trip_share_slug', 'gbp_save_accommodation_oauth_client_secret', 'gbp_vault_delete', 'import_ryoan_order_bypass', 'increment_member_push_badge', 'recalc_course_profit_payouts', 'scan_stuck_group_buy_paid_drafts', 'seed_app_review_account', 'set_discount_code_template_groups', 'set_pricing_template_group_members', 'verify_accommodation_ai_api_key', 'verify_accommodation_api_key', 'verify_owlting_service_account', 'wizard_open_inventory', 'wizard_save_basic_info', 'wizard_save_package', 'wizard_save_room_type');

SELECT COALESCE('GRANT EXECUTE ON FUNCTION public.' || p.proname || '(' || oidvectortypes(p.proargtypes) || ') TO ' || (SELECT string_agg(CASE WHEN a.grantee = 0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(a.grantee)) END, ', ' ORDER BY CASE WHEN a.grantee = 0 THEN 0 ELSE 1 END, pg_get_userbyid(a.grantee)) FROM aclexplode(COALESCE(p.proacl, acldefault('f', p.proowner))) a WHERE a.privilege_type = 'EXECUTE' AND (a.grantee = 0 OR pg_get_userbyid(a.grantee) IN ('anon', 'authenticated', 'service_role'))) || ';', '-- public.' || p.proname || '(' || oidvectortypes(p.proargtypes) || ')：原本 PUBLIC／anon／authenticated／service_role 皆無執行權，不需 GRANT') AS rollback_line
FROM pg_proc p
WHERE p.pronamespace = 'public'::regnamespace AND p.proname IN ('_hotelnabe_enqueue_days', 'acquire_group_buy_payment_hold', 'bulk_upsert_room_inventory_pricing', 'cleanup_old_error_logs', 'cleanup_old_monitoring_logs', 'consume_trip_product_stock', 'convert_group_buy_payment_draft', 'delete_group_buy_campaign', 'gbp_save_accommodation_oauth_client_secret', 'gbp_vault_delete', 'import_ryoan_order_bypass', 'increment_member_push_badge', 'recalc_course_profit_payouts', 'scan_stuck_group_buy_paid_drafts', 'seed_app_review_account', 'verify_accommodation_ai_api_key', 'verify_accommodation_api_key', 'verify_owlting_service_account')
ORDER BY 1;
